# construct 13x13 cropped arrangement, placing 5x5 panels at (1,1),(1,7),(7,1),(7,7)
patterns={1:[[0,0,1],[1,1,1],[0,0,1]],3:[[0,1,1],[0,1,1],[1,0,0]],7:[[0,1,1],[1,1,0],[0,0,1]],5:[[0,1,1],[1,1,0],[0,1,1]]}
out=[[6]*13 for _ in range(13)]
for (y,x),col in zip([(1,1),(1,7),(7,1),(7,7)],[1,3,7,5]):
    for dy in range(5):
        for dx in range(5): out[y+dy][x+dx]=col
    for dy in range(3):
        for dx in range(3):
            if patterns[col][dy][dx]: out[y+1+dy][x+1+dx]=6
print('\n'.join(' '.join(map(str,r)) for r in out))
